import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, output, signal, untracked } from '@angular/core';
import { ClaimsApi, ClaimView } from '../../core/claims';
import { Session } from '../../core/session';

// The paste box: lines of name,amount,date,note each add a DRAFT claim for the named person, all or
// none; how many were added is shown.
@Component({
  selector: 'app-import-people',
  template: `
    <form (submit)="save($event)" aria-label="Paste claims">
      <label for="import-people">Paste claims, one per line: name,amount,date,note</label>
      <textarea
        id="import-people"
        data-testid="import-people"
        rows="4"
        [value]="text()"
        (input)="text.set(value($event)); error.set(null)"
      ></textarea>
      <button type="submit" data-testid="import-submit">Add pasted claims</button>
      @if (added() !== null) {
        <p role="status">Added <strong data-testid="import-added">{{ added() }}</strong> claims.</p>
      }
      @if (error(); as message) {
        <p role="alert" data-testid="import-error">{{ message }}</p>
      }
    </form>
  `,
})
export class ImportPeople {

